// Anti-aliased 4-bit glyph fonts generated by tools/make_bigfont.py.
#pragma once
#include <stdint.h>

struct BigGlyph { char ch; uint32_t off; uint8_t w, h; int8_t dx; int16_t dy; uint8_t adv; };
struct BigFont {
  const BigGlyph *glyphs; int count;
  const uint8_t *bitmap;
  int top, height;          // digit ink rows, relative to the draw origin
};
